WITH src AS (SELECT * FROM inventory WHERE product_id IN (4, 5, 9) AND store_id IN (2, 5, 6)), inventory_stats AS (SELECT MONTH(last_restock) AS last_restock_month, product_id, MIN(quantity) AS min_quantity, MIN(last_restock) AS min_last_restock FROM src GROUP BY MONTH(last_restock), product_id) SELECT * FROM inventory_stats WHERE min_quantity > 120 ORDER BY last_restock_month DESC;
